template.solver:
def solve(a, c, r):
    for N in range(1, 200001):
        P = N*(100-a)/100
        if abs(P-round(P))>1e-9:
            continue
        P = round(P)
        both = P*c/100
        if abs(both-round(both))>1e-9:
            continue
        both = round(both)
        A = P*(100+c)/(100*(1+r))
        if abs(A-round(A))>1e-9:
            continue
        A = round(A)
        B = r*A
        if abs(B-round(B))>1e-9:
            continue
        B = round(B)
        if A-both<0 or B-both<0:
            continue
        if A+B-both!=P:
            continue
        return N
    return 0
